import * as fs from "node:fs";
import * as path from "node:path";

// Chosen numbers: push window 07:00 to 11:00 recipient-local (start included, end excluded);
// a swiped-away card type is withheld until the end of the recipient's local day.
const PUSH_START = "07:00";
const PUSH_END = "11:00";

function stateDir() {
  const dir = process.env.STATE_DIR || path.join(process.cwd(), ".state");
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Sends on one surface once per (user, message id). Returns true when the surface has the item.
async function once(dir, kind, uid, id, send) {
  const key = `${kind}:${uid}:${id}`;
  if (gkRead(dir, `done:${key}`)) return true;
  if (!gkClaim(dir, key)) {
    for (let i = 0; i < 20; i += 1) {
      await sleep(75);
      if (gkRead(dir, `done:${key}`)) return true;
    }
    return false;
  }
  let ok;
  try {
    ok = await send();
  } catch (error) {
    return false; // outcome unknown: keep the claim
  }
  if (ok) {
    gkWrite(dir, `done:${key}`, { at: Date.now() });
    return true;
  }
  gkUnclaim(dir, key); // definitely not sent
  return false;
}

function pushHold(user, nowMs, zone) {
  if (user.notificationsPermitted === false) {
    return { reason: "Push withheld: notifications are turned off for the app in the phone settings.", resume: null };
  }
  if (!gkZoneOk(zone)) {
    return { reason: "Push withheld: the user's time zone is unknown or invalid, so local time cannot be checked.", resume: null };
  }
  let from = nowMs;
  let snoozed = false;
  if (user.snoozedUntil !== null && user.snoozedUntil !== undefined) {
    const s = Date.parse(user.snoozedUntil);
    if (Number.isNaN(s)) {
      return { reason: "Push withheld: the snooze setting could not be read.", resume: null };
    }
    if (s > nowMs) {
      from = s;
      snoozed = true;
    }
  }
  const open = gkNextOpen(from, zone, PUSH_START, PUSH_END);
  if (snoozed || open !== from || !gkInWindow(nowMs, zone, PUSH_START, PUSH_END)) {
    if (open === null) return { reason: "Push withheld by snooze or send hours.", resume: null };
    const when = gkFmt(open, zone);
    const why = snoozed
      ? "the user snoozed notifications"
      : `it is outside morning send hours (${PUSH_START} to ${PUSH_END} local time)`;
    return { reason: `Push withheld: ${why}. It can go out at ${when}.`, resume: new Date(open).toISOString() };
  }
  return null;
}

export async function deliver({ user, candidate, now, transport, consentStore }) {
  const dir = stateDir();
  const nowMs = now instanceof Date ? now.getTime() : typeof now === "number" ? now : Date.parse(now);
  const type = candidate.type;
  const uid = user.id;
  const none = (reason, resumeAt = null) => ({ push: false, inApp: false, reason, resumeAt });

  const pushDone = !!gkRead(dir, `done:push:${uid}:${candidate.id}`);
  const inAppDone = !!gkRead(dir, `done:inapp:${uid}:${candidate.id}`);

  // Consent (applies to both surfaces). Absent or false means off.
  if (!pushDone && !inAppDone) {
    let consents;
    try {
      consents = await consentStore.get(uid);
    } catch (error) {
      return none("Withheld: consent could not be checked right now, so nothing was sent.");
    }
    if (!consents || consents[type] !== true) {
      return none(`Withheld: the user has not given consent for ${type} notifications.`);
    }
    if (user.categories && user.categories[type] === false) {
      return none(`Withheld: the user switched ${type} notifications off in notification settings.`);
    }
    const dis = gkRead(dir, `dismiss:${uid}:${type}`);
    if (dis) {
      const zoneOk = gkZoneOk(user.timezone);
      const same = zoneOk
        ? gkDayKey(dis.at, user.timezone) === gkDayKey(nowMs, user.timezone)
        : nowMs - dis.at < 24 * 3600000;
      if (same) {
        const resume = zoneOk ? gkNextMidnight(dis.at, user.timezone) : null;
        return none(
          `Withheld: the user swiped a ${type} card away today.` + (resume ? ` It can return at ${gkFmt(resume, user.timezone)}.` : ""),
          resume ? new Date(resume).toISOString() : null
        );
      }
    }
  }

  let reason = null;
  let resumeAt = null;
  let push = pushDone;
  if (!pushDone) {
    const hold = pushHold(user, nowMs, user.timezone);
    if (hold) {
      reason = hold.reason;
      resumeAt = hold.resume;
    } else {
      push = await once(dir, "push", uid, candidate.id, () => transport.push(user, candidate));
      if (!push) reason = "Push not delivered: the phone did not accept it (for example no device token).";
    }
  }
  const inApp = await once(dir, "inapp", uid, candidate.id, async () => {
    await transport.inApp(user, candidate);
    return true;
  });
  if (!inApp) reason = reason ? `${reason} The in-app item was not stored.` : "The in-app item was not stored.";
  return { push, inApp, reason: push && inApp ? null : reason, resumeAt: push ? null : resumeAt };
}

export async function recordDismissal(userId, type, now) {
  const dir = stateDir();
  const at = now instanceof Date ? now.getTime() : typeof now === "number" ? now : Date.parse(now);
  const key = `dismiss:${userId}:${type}`;
  const prev = gkRead(dir, key);
  if (!prev || prev.at < at) gkWrite(dir, key, { at });
}
